-- =====================================================================
-- Receivables system -- PostgreSQL / Supabase schema
-- (converted from the MySQL/MariaDB version; same tables and columns)
-- =====================================================================

CREATE TABLE IF NOT EXISTS app_settings (
  setting_key   VARCHAR(100) PRIMARY KEY,
  setting_value TEXT
);

CREATE TABLE IF NOT EXISTS companies (
  id             SERIAL PRIMARY KEY,
  name           VARCHAR(255) NOT NULL UNIQUE,
  code           VARCHAR(50),
  status         VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
  contact_person VARCHAR(255),
  contact_number VARCHAR(50),
  email_address  VARCHAR(255),
  remarks        TEXT,
  created_at     TIMESTAMP(0) DEFAULT (now() AT TIME ZONE 'Asia/Manila'),
  account_type   VARCHAR(20) NOT NULL DEFAULT 'COMPANY',
  branch         VARCHAR(50)
);

CREATE TABLE IF NOT EXISTS ledger_entries (
  id                   SERIAL PRIMARY KEY,
  company_id           INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  billing_date         VARCHAR(50),
  soa_number           VARCHAR(100),
  amount               NUMERIC(15,2) DEFAULT 0.00,
  tax_withheld         NUMERIC(15,2) DEFAULT 0.00,
  surcharge            NUMERIC(15,2) DEFAULT 0.00,
  rebate               NUMERIC(15,2) DEFAULT 0.00,
  receivable_amount    NUMERIC(15,2) DEFAULT 0.00,
  payment_date         VARCHAR(50),
  check_ref            VARCHAR(100),
  paid_amount          NUMERIC(15,2) DEFAULT 0.00,
  balance              NUMERIC(15,2) DEFAULT 0.00,
  due_date             VARCHAR(50),
  remarks              TEXT,
  created_at           TIMESTAMP(0) DEFAULT (now() AT TIME ZONE 'Asia/Manila'),
  updated_at           TIMESTAMP(0) DEFAULT (now() AT TIME ZONE 'Asia/Manila'),
  deduction_remarks    TEXT,
  check_date           VARCHAR(50),
  payment_method       VARCHAR(30),
  payment_method_other VARCHAR(100),
  payment_method_bank  VARCHAR(30),
  company_name         VARCHAR(255)
);
CREATE INDEX IF NOT EXISTS idx_ledger_company      ON ledger_entries(company_id);
CREATE INDEX IF NOT EXISTS idx_ledger_billing_date ON ledger_entries(billing_date);
CREATE INDEX IF NOT EXISTS idx_ledger_soa_number   ON ledger_entries(soa_number);

CREATE TABLE IF NOT EXISTS monitoring_entries (
  id                SERIAL PRIMARY KEY,
  company_id        INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  expected_date     VARCHAR(50),
  amount            NUMERIC(15,2) DEFAULT 0.00,
  remaining_balance NUMERIC(15,2) DEFAULT 0.00,
  due_date          VARCHAR(50),
  remarks           TEXT,
  created_at        TIMESTAMP(0) DEFAULT (now() AT TIME ZONE 'Asia/Manila')
);
CREATE INDEX IF NOT EXISTS idx_monitoring_company ON monitoring_entries(company_id);

CREATE TABLE IF NOT EXISTS soa_tracker (
  id              SERIAL PRIMARY KEY,
  soa_number      VARCHAR(100) NOT NULL,
  company_id      INTEGER REFERENCES companies(id) ON DELETE SET NULL,
  ledger_entry_id INTEGER REFERENCES ledger_entries(id) ON DELETE SET NULL,
  issued_date     TIMESTAMP(0) DEFAULT (now() AT TIME ZONE 'Asia/Manila'),
  status          VARCHAR(20) NOT NULL DEFAULT 'UNUSED'
);
CREATE INDEX IF NOT EXISTS idx_soa_tracker_company ON soa_tracker(company_id);
CREATE INDEX IF NOT EXISTS idx_soa_tracker_ledger  ON soa_tracker(ledger_entry_id);
CREATE INDEX IF NOT EXISTS idx_soa_tracker_number  ON soa_tracker(soa_number);

CREATE TABLE IF NOT EXISTS users (
  id            SERIAL PRIMARY KEY,
  username      VARCHAR(100) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  full_name     VARCHAR(255),
  role          VARCHAR(50) NOT NULL DEFAULT 'admin',
  created_at    TIMESTAMP(0) DEFAULT (now() AT TIME ZONE 'Asia/Manila')
);

-- Supabase exposes every table in the "public" schema through its auto
-- REST API. This app only talks to the database through its own server
-- code, so lock the tables down: with RLS on and no policies, the public
-- API keys can't read or change anything (password hashes included).
ALTER TABLE app_settings       ENABLE ROW LEVEL SECURITY;
ALTER TABLE companies          ENABLE ROW LEVEL SECURITY;
ALTER TABLE ledger_entries     ENABLE ROW LEVEL SECURITY;
ALTER TABLE monitoring_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE soa_tracker        ENABLE ROW LEVEL SECURITY;
ALTER TABLE users              ENABLE ROW LEVEL SECURITY;

